"""Lifelong task generation.

Two generators, selected by config:
- TaskGenerator ("uniform"): goals uniform over free cells != current cell.
  Its RNG call sequence is FROZEN — the m0 golden test depends on it. Never
  insert draws into this path; new sampling schemes get their own class.
- EndpointTaskGenerator ("endpoint"): warehouse-style traffic. Each agent
  alternates between a shelf endpoint (pickup) and a workstation endpoint
  (delivery), starting with a pickup.
- CompetitionRoundRobinTaskGenerator ("competition_rr"): an official-style
  pre-generated uniform task pool, interleaved permanently by agent.
"""

import hashlib

import numpy as np

from lmapf.grid import MOVES, Grid

Cell = tuple[int, int]


def sample_initial_positions(
    grid: Grid, rng: np.random.Generator, n_agents: int
) -> list[Cell]:
    """Distinct random free cells, one per agent. Shared by both generators;
    one rng.choice call, so the RNG stream is identical either way."""
    if n_agents > len(grid.free_cells):
        raise ValueError(
            f"{n_agents} agents but only {len(grid.free_cells)} free cells"
        )
    idx = rng.choice(len(grid.free_cells), size=n_agents, replace=False)
    return [grid.free_cells[i] for i in idx]


class TaskGenerator:
    """Draws goals uniformly from free cells, excluding the agent's current cell.

    All randomness comes from the Generator passed in, so a fixed seed gives a
    fixed task sequence for a fixed sequence of calls.
    """

    def __init__(self, grid: Grid, rng: np.random.Generator):
        if len(grid.free_cells) < 2:
            raise ValueError("grid needs at least 2 free cells for tasks")
        self.grid = grid
        self.rng = rng

    def initial_positions(self, n_agents: int) -> list[Cell]:
        return sample_initial_positions(self.grid, self.rng, n_agents)

    def next_goal(self, agent: int, current: Cell) -> Cell:
        """Uniform over free cells != current (duplicates across agents allowed)."""
        while True:
            goal = self.grid.free_cells[self.rng.integers(len(self.grid.free_cells))]
            if goal != current:
                return goal


def _hash_cells(cells) -> str:
    """Stable provenance hash for a sequence of grid cells."""
    return hashlib.sha256(np.asarray(cells, dtype="<i4").tobytes()).hexdigest()


class CompetitionRoundRobinTaskGenerator:
    """Official-style semantic match for WPPL's ``InfAssignSystem``.

    Starts are sampled distinctly. After starts, one uniform free-cell draw
    creates each element of a fixed task pool. Agent ``k`` receives pool
    indices ``k, k + n_agents, k + 2*n_agents, ...``. A completion changes
    when the next task is revealed, not which latent task that agent receives.

    This intentionally uses NumPy's RNG rather than claiming bitwise identity
    with WPPL's ``std::mt19937`` stream. It matches the probability model and
    assignment semantics. Unlike ``uniform``, same-cell goals are legal and
    no request-time rejection sampling occurs.
    """

    def __init__(self, grid: Grid, rng: np.random.Generator,
                 pool_size: int = 100_000):
        if pool_size < 1:
            raise ValueError("competition task pool must be non-empty")
        self.grid = grid
        self.rng = rng
        self.pool_size = pool_size
        self.task_pool: list[Cell] | None = None
        self.starts: list[Cell] | None = None
        self.n_agents: int | None = None
        self.task_counter: list[int] | None = None
        self.max_task_index = -1

    def initial_positions(self, n_agents: int) -> list[Cell]:
        if self.starts is not None:
            raise RuntimeError("competition starts were already requested")
        self.starts = sample_initial_positions(self.grid, self.rng, n_agents)
        # Exactly one independent uniform free-cell draw per pool element.
        idx = self.rng.integers(len(self.grid.free_cells), size=self.pool_size)
        self.task_pool = [self.grid.free_cells[int(i)] for i in idx]
        self.n_agents = n_agents
        self.task_counter = [0] * n_agents
        return list(self.starts)

    def next_goal(self, agent: int, current: Cell) -> Cell:
        """Reveal the next fixed interleaved task; ``current`` is irrelevant."""
        if self.task_pool is None or self.n_agents is None or self.task_counter is None:
            raise RuntimeError("competition starts must be requested before goals")
        if not 0 <= agent < self.n_agents:
            raise IndexError(f"agent {agent} outside 0..{self.n_agents - 1}")
        index = self.task_counter[agent] * self.n_agents + agent
        if index >= len(self.task_pool):
            raise RuntimeError(
                f"competition task pool exhausted: request index {index} >= "
                f"pool length {len(self.task_pool)}"
            )
        self.task_counter[agent] += 1
        self.max_task_index = max(self.max_task_index, index)
        return self.task_pool[index]

    def provenance(self) -> dict[str, object]:
        """Hashes of latent workload state; does not advance the generator."""
        if self.task_pool is None or self.starts is None or self.n_agents is None:
            raise RuntimeError("competition workload has not been initialized")
        per_agent = [_hash_cells(self.task_pool[k::self.n_agents])
                     for k in range(self.n_agents)]
        return {
            "task_starts_hash": _hash_cells(self.starts),
            "task_initial_goals_hash": _hash_cells(self.task_pool[:self.n_agents]),
            "task_pool_hash": _hash_cells(self.task_pool),
            "task_per_agent_hash": np.asarray(per_agent),
            "task_pool_size": np.int64(len(self.task_pool)),
            "task_max_index": np.int64(self.max_task_index),
        }


def derive_endpoints(
    grid: Grid, stations_per_side: int | None = None
) -> tuple[list[Cell], list[Cell]]:
    """Infer (workstations, shelf_endpoints) from a warehouse-style map.

    Workstations: free cells in the columns adjacent to the left and right
    outer walls (col 1 and col width-2) — the side pick stations of
    RHCR-style warehouses. Shelf endpoints: free cells 4-adjacent to an
    interior obstacle (a shelf block, not the outer wall), excluding
    workstation cells. Every endpoint must have degree >= 2, which makes
    instances well-formed in the sense of Ma et al. 2017 (MAPD). Note this is
    a condition on endpoints only, not a biconnectivity guarantee.
    """
    height, width = grid.height, grid.width
    if "w" in grid.char_cells and "e" in grid.char_cells:
        # Kiva-style annotated map: endpoints are declared, not inferred.
        # stations_per_side is ignored (station count is the map's own).
        workstations = list(grid.char_cells["w"])
        shelf_endpoints = list(grid.char_cells["e"])
        _check_wellformed(grid, workstations, shelf_endpoints)
        return workstations, shelf_endpoints

    workstations = [c for c in grid.free_cells if c[1] in (1, width - 2)]
    if stations_per_side is not None:
        # Deterministic, evenly spaced subset per side (stations are fixed
        # infrastructure — the same for every seed, like a real warehouse).
        # Concentrating demand on few stations is what heats up corridors.
        subset = []
        for col in (1, width - 2):
            side = [c for c in workstations if c[1] == col]
            idx = np.linspace(0, len(side) - 1, stations_per_side).round()
            subset += [side[int(i)] for i in sorted(set(idx.astype(int)))]
        workstations = subset

    shelf_endpoints = []
    for r, c in grid.free_cells:
        if c in (1, width - 2):
            continue
        for dr, dc in MOVES[1:]:
            rr, cc = r + dr, c + dc
            # interior obstacle = shelf block; the outer wall doesn't count
            interior = 1 <= rr <= height - 2 and 1 <= cc <= width - 2
            if interior and grid.obstacles[rr, cc]:
                shelf_endpoints.append((r, c))
                break

    _check_wellformed(grid, workstations, shelf_endpoints)
    return workstations, shelf_endpoints


def _check_wellformed(grid: Grid, workstations: list[Cell], shelf: list[Cell]):
    if not workstations or not shelf:
        raise ValueError(
            f"{grid.name}: endpoint derivation found {len(workstations)} "
            f"workstations and {len(shelf)} shelf endpoints"
        )
    for cell in workstations + shelf:
        if len(grid.neighbors(cell)) < 2:
            raise ValueError(
                f"{grid.name}: endpoint {cell} has degree "
                f"{len(grid.neighbors(cell))} < 2; instance is not well-formed "
                "(Ma et al. 2017)"
            )


class EndpointTaskGenerator:
    """Alternating shelf/workstation goals. Separate code path from
    TaskGenerator so the uniform generator's RNG stream stays frozen."""

    def __init__(
        self,
        grid: Grid,
        rng: np.random.Generator,
        stations_per_side: int | None = None,
    ):
        self.grid = grid
        self.rng = rng
        self.workstations, self.shelf_endpoints = derive_endpoints(
            grid, stations_per_side
        )
        self._next_is_shelf: dict[int, bool] = {}  # per-agent phase

    def initial_positions(self, n_agents: int) -> list[Cell]:
        return sample_initial_positions(self.grid, self.rng, n_agents)

    def next_goal(self, agent: int, current: Cell) -> Cell:
        pool = (
            self.shelf_endpoints
            if self._next_is_shelf.get(agent, True)  # first task is a pickup
            else self.workstations
        )
        self._next_is_shelf[agent] = not self._next_is_shelf.get(agent, True)
        while True:
            goal = pool[self.rng.integers(len(pool))]
            if goal != current:
                return goal


def make_task_generator(
    name: str,
    grid: Grid,
    rng: np.random.Generator,
    stations_per_side: int | None = None,
):
    if name == "uniform":
        return TaskGenerator(grid, rng)
    if name == "competition_rr":
        return CompetitionRoundRobinTaskGenerator(grid, rng)
    if name == "endpoint":
        return EndpointTaskGenerator(grid, rng, stations_per_side)
    raise ValueError(f"unknown task generator {name!r}")

