"""Strict single-step conflict validator.

Any conflict means a planner bug, so validation raises immediately instead of
recording and continuing. Checked every timestep:
  - moves are legal: stay or step to a free 4-neighbour,
  - vertex conflicts: two agents on the same cell after the step,
  - edge-swap conflicts: two agents exchanging cells in one step.
"""

from lmapf.grid import Grid

Cell = tuple[int, int]


class ConflictError(Exception):
    pass


def validate_step(grid: Grid, prev: list[Cell], nxt: list[Cell], t: int) -> None:
    """Validate one transition prev -> nxt (positions indexed by agent)."""
    if len(prev) != len(nxt):
        raise ConflictError(f"t={t}: position list length changed")

    occupied: dict[Cell, int] = {}
    for i, (p, n) in enumerate(zip(prev, nxt, strict=True)):
        if not grid.is_free(n):
            raise ConflictError(f"t={t}: agent {i} moved into blocked cell {n}")
        if abs(n[0] - p[0]) + abs(n[1] - p[1]) > 1:
            raise ConflictError(f"t={t}: agent {i} made illegal move {p} -> {n}")
        if n in occupied:
            raise ConflictError(
                f"t={t}: vertex conflict at {n} between agents {occupied[n]} and {i}"
            )
        occupied[n] = i

    prev_at: dict[Cell, int] = {p: i for i, p in enumerate(prev)}
    for i, (p, n) in enumerate(zip(prev, nxt, strict=True)):
        j = prev_at.get(n)
        # A swap is agent i stepping onto j's old cell while j steps onto i's.
        if j is not None and j != i and nxt[j] == p:
            raise ConflictError(
                f"t={t}: edge-swap conflict between agents {i} and {j} "
                f"on {p} <-> {n}"
            )

