def digest(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def atomic(path: Path, obj, compress=False):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    raw = json.dumps(obj, separators=(",", ":"), default=lambda x: int(x) if isinstance(x, np.integer) else float(x)).encode()
    tmp.write_bytes(gzip.compress(raw, mtime=0) if compress else raw + b"\n")
    os.replace(tmp, path)


