def parse_map(raw: str):
    b = raw.encode("utf-8")
    if len(b) > MAX_MAP_BYTES:
        raise ValueError("map exceeds 100 kB")
    lines = raw.replace("\r\n", "\n").splitlines()
    if len(lines) < 5 or lines[0].strip().lower() != "type octile":
        raise ValueError("MovingAI map must begin with 'type octile'")
    try:
        height = int(lines[1].split()[1]); width = int(lines[2].split()[1])
    except (IndexError, ValueError):
        raise ValueError("expected 'height N' and 'width N' headers") from None
    if lines[3].strip() != "map" or not 2 <= height <= MAX_DIM or not 2 <= width <= MAX_DIM:
        raise ValueError("expected 'map' header and dimensions 2–128")
    rows = lines[4:]
    if len(rows) != height or any(len(row) != width for row in rows):
        raise ValueError(f"expected exactly {height} rows of width {width}; no trailing rows")
    allowed = set(".@OTWGew")
    if any(c not in allowed for row in rows for c in row):
        raise ValueError("unsupported map character; use . G e w for free and @ O T W for blocked")
    obstacles = np.array([[c not in ".Gew" for c in row] for row in rows], dtype=bool)
    annotations = {x: [(r,c) for r,row in enumerate(rows) for c,v in enumerate(row) if v==x] for x in "ew"}
    grid = Grid(obstacles, "assessment", annotations)
    if len(grid.free_cells) < 2:
        raise ValueError("map needs at least two traversable cells")
    free = set(grid.free_cells); seen=set(); sizes=[]
    for start in free:
        if start in seen: continue
        q=deque([start]); seen.add(start); size=0
        while q:
            u=q.popleft(); size+=1
            for v in grid.neighbors(u):
                if v not in seen: seen.add(v);q.append(v)
        sizes.append(size)
    dead=sum(len(grid.neighbors(c))<=1 for c in grid.free_cells)
    warnings=[]
    if len(sizes)>1: warnings.append(f"{len(sizes)} connected components ({sorted(sizes,reverse=True)}); whole-map random starts/tasks may be unreachable. Runs are blocked.")
    if dead: warnings.append(f"{dead} dead-end/isolated traversable cells; PIBT liveness assumptions may not hold here.")
    warnings.append("Connectedness alone does not establish PIBT goal-completion guarantees; bottlenecks, task semantics and priority assumptions matter.")
    return grid,rows,{"width":width,"height":height,"free_cells":len(free),"components":len(sizes),"component_sizes":sorted(sizes,reverse=True),"dead_ends":dead,"warnings":warnings,"map_sha256":digest(b)}


def normalise(config):
    c=dict(config)
    layout=c.get("layout_id","warehouse")
    if layout=="custom":
        raw=c.get("map_text","")
        if not isinstance(raw,str): raise ValueError("custom map text required")
        source={"label":"User-provided MovingAI map", "source":"user upload/editor", "license":"user-supplied; confirm rights before external distribution", "transform":"None"}
    elif layout in LAYOUTS:
        raw=LAYOUTS[layout]["file"].read_text()
        source={k:v for k,v in LAYOUTS[layout].items() if k in ("label","geometry","source","license","transform")}
    else: raise ValueError("unknown layout")
    grid,rows,meta=parse_map(raw)
    if meta["components"]!=1: raise ValueError(meta["warnings"][0])
    try:
        n=int(c.get("n_agents",50)); seed=int(c.get("seed",1)); warm=int(c.get("warmup",20)); scored=int(c.get("scored",80))
    except (ValueError,TypeError): raise ValueError("robot count, seed and horizons must be integers") from None
    if n<1 or n>min(MAX_AGENTS,meta["free_cells"]): raise ValueError(f"robot count must be 1–{min(MAX_AGENTS,meta['free_cells'])}")
    if seed<0 or seed>2**32-1: raise ValueError("seed must be 0–4294967295")
    if warm<0 or scored<1 or warm+scored>MAX_TOTAL_STEPS: raise ValueError(f"need warm-up ≥0, scored ≥1 and total ≤{MAX_TOTAL_STEPS}")
    mode=c.get("task_mode","competition_rr")
    if mode not in ("competition_rr","uniform","endpoint"): raise ValueError("task mode must be competition_rr, uniform or endpoint")
    if mode=="endpoint":
        try: EndpointTaskGenerator(grid,np.random.default_rng(0))
        except ValueError as e: raise ValueError(f"endpoint mode unavailable on this map: {e}") from e
    wanted=c.get("planner","compare")
    if wanted not in ("UU","GG","compare"): raise ValueError("planner must be UU, GG or compare")
    compatible=next((key for key,v in LAYOUTS.items() if v.get("guidance") is not None and meta["map_sha256"]==v["sha256"] and layout==key),None)
    # Even a custom byte-identical map is not automatically identified as a
    # published geometry; upload must be explicitly selected as a known map.
    if wanted in ("GG","compare") and not compatible:
        raise ValueError("no exact published guidance field for this selected map; choose UU baseline only")
    if compatible:
        # Load and validate geometry/indexing/positive weights before enabling.
        weights=load_guidance(LAYOUTS[compatible]["guidance"],grid)
        if np.any(weights.array[~np.isnan(weights.array)]<=0): raise ValueError("nonpositive guidance weight")
    c={"layout_id":layout,"map_text":raw if layout=="custom" else None,"n_agents":n,"seed":seed,"warmup":warm,"scored":scored,"task_mode":mode,"planner":wanted,"task_pool_size":min(MAX_POOL,max(n*30,n*(warm+scored+2))) if mode=="competition_rr" else None}
    return c,raw,rows,meta,source,compatible


class AssessmentSimulator(BoundarySimulator):
    """Task-generator adapter; all planning/advance/accounting is inherited."""
    def __init__(self,planner,tasks,positions,goals,configuration):
        if type(tasks) is CompetitionRoundRobinTaskGenerator:
            super().__init__(planner,tasks,positions,goals,configuration); return
        self.planner=planner;self.tasks=tasks;self.positions=list(positions);self.goals=list(goals)
        self.configuration=configuration;self.timestep=0;self._planning=False;self._bfs={}
        n=len(positions);self.trip_started=[0]*n
        self.trip_initial_distance=[self.distance(p,g) for p,g in zip(positions,goals)]
        self.trip_steps=[0]*n;self.trip_cost=[0]*n;self.trip_waits=[0]*n;self.trip_backward=[0]*n
        self.completed_trips=[];self.total_cost=0;self.total_waits=0;self.total_backward=0;self.total_completions=0


def make_sim(c,raw,compatible,arm):
    grid,rows,meta=parse_map(raw)
    task_rng=np.random.default_rng([c["seed"],1]);planner_rng=np.random.default_rng([c["seed"],2]);order_rng=np.random.default_rng([c["seed"],3])
    if c["task_mode"]=="competition_rr":tasks=CompetitionRoundRobinTaskGenerator(grid,task_rng,c["task_pool_size"])
    else:tasks=make_task_generator(c["task_mode"],grid,task_rng)
    positions=tasks.initial_positions(c["n_agents"])
    goals=[tasks.next_goal(i,p) for i,p in enumerate(positions)]
    unit=EdgeWeights(grid)
    weights=unit if arm=="UU" else load_guidance(LAYOUTS[compatible]["guidance"],grid)
    planner=PIBT(grid,planner_rng,order_rng=order_rng,root_weights=weights,inherited_weights=weights)
    return AssessmentSimulator(planner,tasks,positions,goals,{"config":c,"map_sha256":digest(raw.encode()),"arm":arm})


def _event_from_observer(observer,t):
    failed=[(cid,q) for cid,c in observer.calls.items() for q in c["candidates"] if q.get("recursive_outcome")=="failure"]
    if not failed:return None
    root=observer.calls[failed[0][0]]["root_call_id"]
    tree=sorted((c for c in observer.calls.values() if c["root_call_id"]==root),key=lambda x:x["call_id"])
    spine=[];current=root
    while True:
        spine.append(current)
        child=next((q.get("recursive_child_call_id") for q in observer.calls[current]["candidates"] if q.get("final_committed_candidate") and q.get("recursive_outcome")=="success"),None)
        if child is None:break
        current=child
    return {"timestep":t,"root_call_id":root,"spine_call_ids":spine,"calls":tree,"semantics":"Recorded callbacks and post-failed-return assignments; no inferred earlier states."}


def quantiles(values):
    return {"count":len(values),"mean":float(np.mean(values)) if values else None,"p50":float(np.percentile(values,50)) if values else None,"p90":float(np.percentile(values,90)) if values else None,"max":max(values) if values else None}


def run_one(job,c,raw,rows,meta,source,compatible,arm,steps=None,persist=True):
