    compact=lambda cells:[p[0]*width+p[1] for p in cells]
    initial_pos=compact(sim.positions);initial_goals=compact(sim.goals)
    frames=[{"t":0,"p":initial_pos,"g":initial_goals}]
    completed=[];step_rows=[];event=None
    scored_wait=scored_back=scored_cost=scored_tasks=scored_plan=0
    scored_root=scored_inherited=scored_inspect=scored_failed=0
    root_back=0;max_age=0;start_cpu=time.process_time()
    for t in range(1,total+1):
        before=tuple(sim.positions)
        old=len(sim.completed_trips)
        if event is None and t<=16:
            observer=EventObserver(sim.planner)
            with patch.object(full,"StepCounters",lambda:observer): result=sim.advance(True)
            event=_event_from_observer(observer,t)
        else: result=sim.advance(True)
        validate_step(sim.planner.grid,before,sim.positions,t)
        inherited=set(sim.planner.last_children)
        flags=[r["wait"]+2*r["backward"] for r in result["agents"]]
        frame={"t":t,"p":compact(sim.positions),"g":compact(sim.goals),"m":flags,"h":sorted(inherited),"done":[r["agent"] for r in result["agents"] if r["task_completed"]],"cost":result["cost"],"wait":result["wait"],"backward":result["backward"],"completed":result["task_completed"],"root_calls":result["root_calls"],"inherited_calls":result["inherited_calls"],"candidate_inspections":result["candidate_inspections"],"failed_child_returns":result["failed_child_returns"]}
        frames.append(frame)
        for trip in sim.completed_trips[old:]:
            if trip[2]>c["warmup"]:
                completed.append({"agent":trip[0],"start":trip[1],"end":trip[2],"steps":trip[3],"initial_distance":trip[4],"cost":trip[5],"wait":trip[6],"backward":trip[7]})
        if t>c["warmup"]:
            scored_wait+=result["wait"];scored_back+=result["backward"];scored_cost+=result["cost"]
            scored_tasks+=result["task_completed"];scored_plan+=result["planning_seconds"]
            scored_root+=result["root_calls"];scored_inherited+=result["inherited_calls"]
            scored_inspect+=result["candidate_inspections"];scored_failed+=result["failed_child_returns"]
            root_back+=sum(r["backward"] for r in result["agents"] if r["agent"] not in inherited)
            max_age=max(max_age,max(sim.planner.time_since_goal))
        step_rows.append({"t":t,"completed":result["task_completed"],"wait":result["wait"],"backward":result["backward"],"planning_seconds":result["planning_seconds"],"candidate_inspections":result["candidate_inspections"],"failed_child_returns":result["failed_child_returns"]})
        if persist and (t%2==0 or t==total): atomic(job/"progress.json",{"status":"running","arm":arm,"transition":t,"total":total,"cpu_seconds":time.process_time()-start_cpu})
    unfinished=[{"agent":i,"age":sim.trip_steps[i],"remaining_distance":sim.distance(p,g),"wait":sim.trip_waits[i],"backward":sim.trip_backward[i]} for i,(p,g) in enumerate(zip(sim.positions,sim.goals))]
    duration=[r["steps"] for r in completed];delay=[r["cost"] for r in completed]
    summary={"arm":arm,"seed":c["seed"],"n_agents":n,"free_cells":meta["free_cells"],"occupancy":n/meta["free_cells"],"warmup":c["warmup"],"scored_transitions":c["scored"] if steps is None else max(0,total-c["warmup"]),"scored_completed_tasks":scored_tasks,"throughput":scored_tasks/max(1,total-c["warmup"]),"scored_wait_actions":scored_wait,"scored_backward_actions":scored_back,"scored_cost":scored_cost,"wait_rate":scored_wait/max(1,n*(total-c["warmup"])),"backward_rate":scored_back/max(1,n*(total-c["warmup"])),"scored_root_calls":scored_root,"scored_inherited_calls":scored_inherited,"scored_candidate_inspections":scored_inspect,"scored_failed_child_returns":scored_failed,"scored_root_backward":root_back,"planning_seconds":scored_plan,"planning_seconds_per_step":scored_plan/max(1,total-c["warmup"]),"completed_trip_duration":quantiles(duration),"completed_trip_delay":quantiles(delay),"unfinished_age":quantiles([x["age"] for x in unfinished]),"unfinished_remaining_distance":quantiles([x["remaining_distance"] for x in unfinished]),"max_task_age":max_age,"collision_validation":"passed: every transition checked for legal move, vertex and reverse-edge-swap conflicts","map_sha256":meta["map_sha256"],"task_mode":c["task_mode"],"task_pool_size":c["task_pool_size"],"guidance_source":str(LAYOUTS[compatible]["guidance_source"]) if arm=="GG" else None,"guidance_sha256":LAYOUTS[compatible]["guidance_sha256"] if arm=="GG" else None,"guidance_training":LAYOUTS[compatible]["training"] if arm=="GG" else None,"starts_sha256":digest(np.asarray(initial_pos,dtype='<i4').tobytes()),"initial_goals_sha256":digest(np.asarray(initial_goals,dtype='<i4').tobytes()),"worker_cpu_seconds":time.process_time()-start_cpu,"peak_rss_kib":resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}
    if type(sim.tasks) is CompetitionRoundRobinTaskGenerator: summary["latent_task_pool_sha256"]=sim.tasks.provenance()["task_pool_hash"]
    if persist:
        atomic(job/f"{arm}_trace.json.gz",{"schema":2,"summary":summary,"width":width,"height":meta["height"],"layout":rows,"frames":frames,"event":event,"map_sha256":meta["map_sha256"]},True)
        atomic(job/f"{arm}_completed.json",completed)
        atomic(job/f"{arm}_unfinished.json",unfinished)
        atomic(job/f"{arm}_steps.json",step_rows)
        atomic(job/f"{arm}_summary.json",summary)
    return summary


def worker_main(job_id):
    job=RUNS/job_id
    payload=json.loads((job/"input.json").read_text());c=payload["config"]
    c,raw,rows,meta,source,compatible=normalise(c)
    resource.setrlimit(resource.RLIMIT_AS,(2*1024**3,)*2)
    cpu_limit=max(1,min(90,int(os.environ.get("ASSESS_CPU_LIMIT","90"))))
    resource.setrlimit(resource.RLIMIT_CPU,(cpu_limit,cpu_limit))
    arms=["UU","GG"] if c["planner"]=="compare" else [c["planner"]]
    summaries=[]
    for arm in arms:summaries.append(run_one(job,c,raw,rows,meta,source,compatible,arm))
    if len(summaries)==2:
        assert summaries[0]["starts_sha256"]==summaries[1]["starts_sha256"]
        assert summaries[0]["initial_goals_sha256"]==summaries[1]["initial_goals_sha256"]
        if c["task_mode"]=="competition_rr":assert summaries[0]["latent_task_pool_sha256"]==summaries[1]["latent_task_pool_sha256"]
    atomic(job/"result.json",{"status":"complete","config":c,"map":meta,"source":source,"summaries":summaries,"arms":arms,"paired_inputs":len(arms)==2})
    print(json.dumps({"status":"complete","arms":arms}))


if __name__=="__main__":
    if len(sys.argv)>2 and sys.argv[2]=="pilot":
        resource.setrlimit(resource.RLIMIT_AS,(2*1024**3,)*2)
        resource.setrlimit(resource.RLIMIT_CPU,(15,15))
        payload=json.loads((RUNS/sys.argv[1]/"input.json").read_text())
        c,raw,rows,meta,source,compatible=normalise(payload["config"])
        arms=["UU","GG"] if c["planner"]=="compare" else [c["planner"]]
        t0=time.process_time()
        for arm in arms:run_one(RUNS/sys.argv[1],c,raw,rows,meta,source,compatible,arm,steps=min(10,c["warmup"]+c["scored"]),persist=False)
        print(json.dumps({"pilot_cpu_seconds":time.process_time()-t0,"pilot_steps":min(10,c["warmup"]+c["scored"]),"arms":arms}))
    else:worker_main(sys.argv[1])
